#include <iostream>
#include <queue>
#include <cstring>
#include <climits>
#include <algorithm>
#include <chrono>
#include <random>
using namespace std;

using ll = long long;
using pii = pair<int, int>;

mt19937_64 mt(chrono::steady_clock::now().time_since_epoch().count());

const int MAXN = 12;
const int INF = 1000000009;
const int dr[4] = {0, 1, 0, -1};
const int dc[4] = {1, 0, -1, 0};

int n, t;
char M1[MAXN][MAXN], M2[MAXN][MAXN];
int dis[MAXN][MAXN];
bool mark[MAXN][MAXN];

struct Pos {
    int r, c;
    Pos() {}
    Pos(int r, int c) : r(r), c(c) {}
};

void bfs_dis(int sr, int sc) {
    for (int i = 0; i < n; ++i) fill(dis[i], dis[i] + n, INF);
    memset(mark, 0, sizeof(mark));
    queue<Pos> q;
    mark[sr][sc] = true;
    dis[sr][sc] = 0;
    q.emplace(sr, sc);
    while (!q.empty()) {
        Pos cur = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nr = cur.r + dr[i], nc = cur.c + dc[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n && !mark[nr][nc] && isdigit(M1[nr][nc])) {
                mark[nr][nc] = true;
                dis[nr][nc] = dis[cur.r][cur.c] + 1;
                q.emplace(nr, nc);
            }
        }
    }
}

bool dp[72][12][12][12][12];
bool reachable[12][12][12][12];

int cap[290][290];
int prev_node[290];
bool visited[290];

bool find_augmenting_path() {
    memset(visited, 0, sizeof(visited));
    memset(prev_node, 0, sizeof(prev_node));
    queue<int> q;
    visited[0] = true;
    q.push(0);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        if (u == 2 * n * n + 1) return true;
        for (int v = 0; v <= 2 * n * n + 1; ++v) {
            if (cap[u][v] && !visited[v]) {
                visited[v] = true;
                prev_node[v] = u;
                q.push(v);
            }
        }
    }
    return false;
}

void main_logic() {
    cin >> n >> t;
    for (int i = 0; i < n; ++i) cin >> M1[i];
    for (int i = 0; i < n; ++i) cin >> M2[i];
    int sr, sc;
    cin >> sr >> sc;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (M1[i][j] == 'Z') {
                sr = i; sc = j;
            }
        }
    }
    bfs_dis(sr, sc);
    memset(dp, 0, sizeof(dp));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(M1[i][j])) {
                dp[0][i][j][i][j] = true;
            }
        }
    }
    for (int step = 0; step < t; ++step) {
        for (int pr = 0; pr < n; ++pr) {
            for (int pc = 0; pc < n; ++pc) {
                for (int r = 0; r < n; ++r) {
                    for (int c = 0; c < n; ++c) {
                        if (!dp[step][pr][pc][r][c]) continue;
                        if (dis[r][c] <= step) continue;
                        for (int k = 0; k < 4; ++k) {
                            int nr = r + dr[k], nc = c + dc[k];
                            if (nr >= 0 && nr < n && nc >= 0 && nc < n && isdigit(M1[nr][nc]) && dis[nr][nc] >= step + 1) {
                                dp[step + 1][pr][pc][nr][nc] = true;
                            }
                        }
                    }
                }
            }
        }
    }
    memset(reachable, 0, sizeof(reachable));
    for (int step = 0; step <= t; ++step) {
        for (int pr = 0; pr < n; ++pr) {
            for (int pc = 0; pc < n; ++pc) {
                for (int r = 0; r < n; ++r) {
                    for (int c = 0; c < n; ++c) {
                        if (dp[step][pr][pc][r][c]) {
                            reachable[pr][pc][r][c] = true;
                        }
                    }
                }
            }
        }
    }
    memset(cap, 0, sizeof(cap));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(M1[i][j])) {
                cap[0][i * n + j + 1] = M1[i][j] - '0';
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(M2[i][j])) {
                cap[n * n + i * n + j + 1][2 * n * n + 1] = M2[i][j] - '0';
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (!isdigit(M1[i][j])) continue;
            for (int k = 0; k < n; ++k) {
                for (int l = 0; l < n; ++l) {
                    if (!isdigit(M1[k][l])) continue;
                    if (!reachable[i][j][k][l]) continue;
                    cap[i * n + j + 1][n * n + k * n + l + 1] = INF;
                }
            }
        }
    }
    while (find_augmenting_path()) {
        int f = INF;
        for (int u = 2 * n * n + 1; u; u = prev_node[u]) {
            f = min(f, cap[prev_node[u]][u]);
        }
        for (int u = 2 * n * n + 1; u; u = prev_node[u]) {
            cap[prev_node[u]][u] -= f;
            cap[u][prev_node[u]] += f;
        }
    }
    int max_flow = 0;
    for (int i = 0; i <= 2 * n * n + 1; ++i) {
        max_flow += cap[i][0];
    }
    cout << max_flow << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    main_logic();
    return 0;
}
